package com.bank.caveats.id;

import java.security.SecureRandom;
import java.util.Base64;

// For security tokens we need FULL cryptographic randomness with NO time prefix,
// precisely because a UUIDv7 would leak time and be partly predictable.
public class SecureTokenGenerator {
    private static final SecureRandom RANDOM = new SecureRandom();

    public String newToken() {
        byte[] bytes = new byte[32];           // 256 bits of pure randomness
        RANDOM.nextBytes(bytes);
        return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
    }
}
