package com.bank.caveats.service;

import com.bank.caveats.id.UuidV7;
import com.bank.caveats.model.Transaction;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import java.time.LocalDateTime;
import java.util.Comparator;
import java.util.List;
import java.util.UUID;

@Service
public class SettlementService {
    private static final Logger log = LoggerFactory.getLogger(SettlementService.class);

    public UUID newInternalKey() {
        // UUIDv7 is a fine internal key (locality), stored as native uuid
        return UuidV7.generate();
    }

    // CAVEAT 1: order by the explicit event_time column, NOT by the UUIDv7 id,
    // because cross-node clock skew makes the id only approximately ordered.
    public List<Transaction> settleInTrueOrder(List<Transaction> txns) {
        log.warning("Ordering by explicit event_time, NOT UUIDv7 prefix (clock skew across nodes)");
        return txns.stream()
                   .sorted(Comparator.comparing(Transaction::getEventTime))
                   .toList();
    }
}
